[{"Name":"펼치기","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/wa_skill/wa_skill_01_4.png","Level":3,"Type":"일반","SkillType":0,"Tripods":[{"Tier":0,"Slot":1,"Name":"기류 발생","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_1_154.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>공격 적중 시 빗방울 게이지 획득량이 <FONT COLOR='#ff9999'>30.0%</FONT> 줄어들지만 <FONT COLOR='#ffff99'>4.0</FONT>초간 자신의 최대 생명력에 <FONT COLOR='#99ff99'>15.0%</FONT>에 해당하는 기류 보호막이 생성된다.</font>"},{"Tier":0,"Slot":2,"Name":"급소 노출","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_1_99.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>공격 적중 시 대상이 자신 및 파티원에게 받는 치명타 저항률이 <FONT COLOR='#ffff99'>8.0</FONT>초간 <FONT COLOR='#99ff99'>10.0%</FONT> 감소한다.</font>"},{"Tier":0,"Slot":3,"Name":"증기 획득","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_1_37.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>공격 적중 시 빗방울 게이지 회복량이 <FONT COLOR='#99ff99'>75.0%</FONT> 증가한다.</font>"},{"Tier":1,"Slot":1,"Name":"외부 충격","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_2_44.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>마지막 공격 적중 시 <FONT COLOR='#ffff99'>3.0</FONT>초간 기절 상태로 만든다. 재사용 대기시간이 <FONT COLOR='#ff9999'>7.0</FONT>초 증가한다.</font>"},{"Tier":1,"Slot":2,"Name":"가벼운 발걸음","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_2_11.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>스킬 시전 시 <FONT COLOR='#ffff99'>4.0</FONT>초간 자신의 이동속도가 <FONT COLOR='#99ff99'>30.0%</FONT> 증가한다.</font>"},{"Tier":1,"Slot":3,"Name":"마나 순환","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_2_79.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>마지막 공격 적중 시 <FONT COLOR='#99ff99'>206</FONT>의 마나를 돌려받는다.</font>"},{"Tier":2,"Slot":1,"Name":"날카로운 장막","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_3_39.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>스킬 사용 시 우산을 펼친 채 돌진하는 추가 공격이 발생하고, 적중 시 우산을 접으며 전방의 적을 자신의 앞으로 당겨오며 적에게 주는 피해가 <FONT COLOR='#99ff99'>105.0%</FONT> 증가한다.</font>"},{"Tier":2,"Slot":2,"Name":"거대 장막","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/tripod_tier/tripod_tier_3_7.png","IsSelected":false,"Tooltip":"<font color='#FFFDE7'>스킬 사용 즉시 거대한 파라솔을 펼쳐 공격하는 형태로 변경되며 공격 범위가 <FONT COLOR='#99ff99'>100.0%</FONT> 증가하고 적에게 주는 피해가 <FONT COLOR='#99ff99'>95.0%</FONT> 증가한다.</font>"}],"Rune":{"Name":"속행","Icon":"https://cdn-lostark.game.onstove.com/efui_iconatlas/use/use_7_196.png","Grade":"전설","Tooltip":"{"Element_000":{"type":"NameTagBox","value":"<P ALIGN='CENTER'><FONT COLOR='#F99200'>속행</FONT></P>"},"Element_001":{"type":"ItemTitle","value":{"bEquip":0,"itemIrochiCount":0,"leftStr0":"<FONT SIZE='12'><FONT COLOR='#F99200'>전설 스킬 룬</FONT></FONT>","leftStr1":"","leftStr2":"","qualityValue":-1,"rightStr0":"","slotData":{"advBookIcon":0,"battleItemTypeIcon":0,"blackListIcon":0,"cardIcon":false,"friendship":0,"iconGrade":4,"iconPath":"efui_iconatlas/use/use_7_196.png","imagePath":"","islandIcon":0,"petBorder":0,"rtString":"","temporary":0,"town":0,"trash":0}}},"Element_002":null,"Element_003":{"type":"ItemPartBox","value":{"Element_000":"<FONT COLOR='#A9D0F5'>스킬 룬 효과</FONT>","Element_001":"스킬 사용 시 일정 확률로 전체 재사용 대기 시간이 16% 감소"}},"Element_004":{"type":"SingleTextBox","value":"<FONT COLOR='#E2C87A'><FONT SIZE='12'>스킬에 강력한 힘을 부여할 수 있는 특별한 룬이다.</FONT></FONT>"},"Element_005":{"type":"Progress","value":null},"Element_006":{"type":"Progress","value":null},"Element_007":{"type":"SingleTextBox","value":"<Font color='#5FD3F1'>[퀘스트] 플레체 - 플레체의 장미</font>"}}"},"Tooltip":"{
